from collections import defaultdict

corpus = ["the cat sat on the mat", "the dog sat on the rug"]
window_size = 2  # already covered as the local context window in Word2Vec

cooccurrence = defaultdict(lambda: defaultdict(int))  # already covered as the co-occurrence matrix in this topic

for sentence in corpus:
    words = sentence.split()
    for i, target in enumerate(words):
        start = max(0, i - window_size)
        end = min(len(words), i + window_size + 1)
        for j in range(start, end):
            if j != i:
                # already covered as counting co-occurrences across the entire corpus in this topic
                cooccurrence[target][words[j]] += 1

print("Co-occurrence counts for 'sat' (already covered as the co-occurrence matrix in this topic):")
for context_word, count in cooccurrence["sat"].items():
    print(f"  '{context_word}': {count}")

print("\nGloVe would factorize a full matrix like this, already covered as matrix factorization in this topic,")
print("into dense word vectors, rather than predicting words directly like Skip-gram does")
